  "Первый в Таиланде танцпол-в-бассейне: 3 000 м², два бассейна, вечеринки день-в-ночь. Открыт в 2025.": "First dance floor in a pool in Thailand: 3,000 sqm, two pools, day-to-night parties. Opened in 2025.",
