  "Именно มังสวิรัติ, а не เจ: เจ — строгая буддийская кухня без чеснока и лука, и заказ выйдет другим.": "Say มังสวิรัติ, not เจ: เจ is strict Buddhist cuisine without garlic or onion, and you'll get a different dish.",
  "Вегетарианцу это нужно отдельно: в Таиланде рыбный соус кладут почти во всё, включая овощные блюда.": "Vegetarians need this one separately: in Thailand fish sauce goes into almost everything, even vegetable dishes.",
  "Вопрос: у женщины คะ с восходящим тоном, не ค่ะ.": "It's a question: women use คะ with a rising tone, not ค่ะ.",
  "น้ำเปล่า — именно питьевая вода. Просто น้ำ официант может понять как любой напиток.": "น้ำเปล่า means plain drinking water. Just น้ำ may be taken as any drink.",
