  "Все заведения острова точками — от Патонга до Ката": "ทุกสถานที่บนเกาะเป็นจุด — ตั้งแต่ป่าตองถึงกะตะ",
  "Движок сопоставит жанры и корпус афиш вашей площадки с 312 артистами базы и гастролёрами по Азии — и предложит лайнап до того, как их забукают конкуренты.": "ระบบจะจับคู่แนวเพลงและประวัติอีเวนต์ของสถานที่คุณกับศิลปิน 312 คนในฐานข้อมูลและศิลปินทัวร์ทั่วเอเชีย — แล้วเสนอไลน์อัปก่อนที่คู่แข่งจะจองตัวไป",
