  "Подключение Spotify и визуальная статистика вашего вкуса — фаза B. Как только запустим, здесь появится кнопка подключения.": "เชื่อมต่อ Spotify และดูสถิติรสนิยมของคุณ — เฟส B เมื่อเปิดใช้งาน ปุ่มเชื่อมต่อจะปรากฏตรงนี้",
  "Подключите музыкальный профиль — движок сопоставит ваши жанры и любимых артистов с афишами 110 заведений и предложит, куда идти сегодня.": "เชื่อมโปรไฟล์ดนตรีของคุณ — ระบบจะจับคู่แนวเพลงและศิลปินที่คุณชอบกับโปรแกรมของ 110 สถานที่ แล้วบอกว่าคืนนี้ควรไปไหน",
